#banner.pop { animation: bannerIn 0.45s ease-out; }
@keyframes bannerIn { from { opacity: 0; transform: translateX(-50%) scale(0.85); } to { opacity: 1; transform: translateX(-50%) scale(1); } }
#banner-title { font-size: 44px; font-weight: 900; letter-spacing: 3px; color: #ffd24a; text-shadow: 0 3px 0 #7a2d1e, 0 6px 18px rgba(0,0,0,0.8); }
#banner-sub { font-size: 17px; margin-top: 6px; text-shadow: 0 2px 6px rgba(0,0,0,0.9); }
#damage-flash { position: absolute; inset: 0; background: radial-gradient(ellipse at center, transparent 55%, rgba(255,30,20,0.85) 100%); opacity: 0; transition: opacity 0.25s; pointer-events: none; }
#hint { position: absolute; bottom: 14px; left: 50%; transform: translateX(-50%); font-size: 13px; color: rgba(255,255,255,0.75); text-shadow: 0 1px 4px #000; white-space: nowrap; }
.menu { position: fixed; inset: 0; z-index: 10; display: flex; align-items: center; justify-content: center; background: linear-gradient(180deg, rgba(28,20,69,0.55), rgba(255,126,74,0.35)); }
.menu-card { text-align: center; background: rgba(12,10,28,0.82); border: 1px solid rgba(255,210,74,0.5); border-radius: 18px; padding: 36px 44px; max-width: 620px; box-shadow: 0 20px 60px rgba(0,0,0,0.6); }
.menu-card h1 { font-size: 58px; font-weight: 900; letter-spacing: 6px; color: #ffd24a; text-shadow: 0 4px 0 #7a2d1e; }
.tagline { font-size: 17px; color: #ffb36b; margin-top: 4px; font-style: italic; }
.story { font-size: 15px; line-height: 1.55; margin: 16px 0; color: #e8e4da; }
.controls-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px 18px; text-align: left; font-size: 14px; margin: 14px auto 20px; max-width: 420px; }
.controls-grid b { color: #ffd24a; }
.big-btn { display: block; margin: 10px auto 0; padding: 13px 42px; font-size: 18px; font-weight: 800; letter-spacing: 1px; color: #1c1445; background: #ffd24a; border: none; border-radius: 10px; cursor: pointer; pointer-events: auto; }
.big-btn:hover { background: #ffe28a; }
.big-btn.ghost { background: transparent; color: #ffd24a; border: 2px solid #ffd24a; font-size: 15px; padding: 9px 28px; }
.fine { font-size: 12px; color: rgba(255,255,255,0.55); margin-top: 16px; }
